app.post('/api/cards/blackjack/start',verified,csrf,wrap(async(q,r)=>{const d=playingDeck(),player=[d.pop(),d.pop()],dealer=[d.pop(),d.pop()],pt=blackjackTotal(player),dt=blackjackTotal(dealer);let outcome=null,rewardPoints=0;if(pt===21){outcome=dt===21?'draw': 'win';}const result=await tx(async c=>{const x=await c.query(`INSERT INTO game_sessions(user_id,game_id,mode,status,state,score,reward_points,finished_at) VALUES($1,'blackjack','bot',$2,$3,$4,$5,CASE WHEN $2='complete' THEN now() END) RETURNING id`,[q.session.uid,outcome?'complete':'active',JSON.stringify({deck:d,player,dealer,outcome}),outcome==='win'?1:0,outcome==='win'?25:0]);if(outcome==='win'){rewardPoints=await awardGameWin(c,q.session.uid,x.rows[0].id,25);await c.query('UPDATE game_sessions SET reward_points=$2 WHERE id=$1',[x.rows[0].id,rewardPoints])}return x.rows[0].id});r.status(201).json({id:result,player,dealer:outcome?dealer:[dealer[0]],playerTotal:pt,active:!outcome,outcome,rewardPoints})}));
app.post('/api/cards/blackjack/action',verified,csrf,wrap(async(q,r)=>{const {gameId,action}=q.body;if(typeof gameId!=='string'||!['hit','stand'].includes(action))return r.status(400).json({error:'Acción no válida.'});const result=await tx(async c=>{const row=await c.query(`SELECT state,status,started_at FROM game_sessions WHERE id=$1 AND user_id=$2 AND game_id='blackjack' AND mode='bot' FOR UPDATE`,[gameId,q.session.uid]);if(!row.rowCount||row.rows[0].status!=='active')return null;const state=row.rows[0].state;if(action==='hit'){state.player.push(state.deck.pop());if(blackjackTotal(state.player)>21)state.outcome='loss'}else{while(blackjackTotal(state.dealer)<17)state.dealer.push(state.deck.pop());const p=blackjackTotal(state.player),d=blackjackTotal(state.dealer);state.outcome=p>21?'loss':d>21||p>d?'win':p<d?'loss':'draw'}let rewardPoints=0;if(state.outcome){const won=state.outcome==='win';await c.query(`UPDATE game_sessions SET status='complete',state=$2,score=$3,reward_points=$4,finished_at=now() WHERE id=$1`,[gameId,JSON.stringify(state),won?1:0,won?25:0]);if(won){rewardPoints=await awardGameWin(c,q.session.uid,gameId,25);await c.query('UPDATE game_sessions SET reward_points=$2 WHERE id=$1',[gameId,rewardPoints])}}else await c.query('UPDATE game_sessions SET state=$2 WHERE id=$1',[gameId,JSON.stringify(state)]);return{player:state.player,dealer:state.outcome?state.dealer:[state.dealer[0]],playerTotal:blackjackTotal(state.player),dealerTotal:state.outcome?blackjackTotal(state.dealer):null,active:!state.outcome,outcome:state.outcome,rewardPoints}});if(!result)return r.status(409).json({error:'La partida ya terminó o no existe.'});r.json(result)}));
