app.post('/api/cards/war/draw',verified,csrf,wrap(async(q,r)=>{const {gameId}=q.body;if(typeof gameId!=='string')return r.status(400).json({error:'Partida no válida.'});const result=await tx(async c=>{const row=await c.query(`SELECT state,status,started_at FROM game_sessions WHERE id=$1 AND user_id=$2 AND game_id='war' AND mode='bot' FOR UPDATE`,[gameId,q.session.uid]);if(!row.rowCount||row.rows[0].status!=='active')return null;const s=row.rows[0].state;if(!s.you.length||!s.bot.length)return null;const pile=[];let a,b,war=false;do{a=s.you.pop();b=s.bot.pop();pile.push(a,b);if(a.value!==b.value)break;if(s.you.length&&s.bot.length){war=true;for(let i=0;i<3&&s.you.length&&s.bot.length;i++)pile.push(s.you.pop(),s.bot.pop())}else break}while(a.value===b.value&&s.you.length&&s.bot.length);let resultName='tie';if(a.value>b.value){s.you.push(...pile);resultName='you'}else if(b.value>a.value){s.bot.push(...pile);resultName='bot'}else{s.you.push(...pile.slice(0,Math.ceil(pile.length/2)));s.bot.push(...pile.slice(Math.ceil(pile.length/2)));}const outcome=s.you.length===0?'loss':s.bot.length===0?'win':null;s.last={you:a,bot:b,war,result:resultName};let rewardPoints=0;if(outcome){const won=outcome==='win';await c.query(`UPDATE game_sessions SET status='complete',state=$2,score=$3,reward_points=$4,finished_at=now() WHERE id=$1`,[gameId,JSON.stringify({...s,outcome}),won?1:0,won?25:0]);if(won){rewardPoints=await awardGameWin(c,q.session.uid,gameId,25);await c.query('UPDATE game_sessions SET reward_points=$2 WHERE id=$1',[gameId,rewardPoints])}}else await c.query('UPDATE game_sessions SET state=$2 WHERE id=$1',[gameId,JSON.stringify(s)]);return{you:a,bot:b,war,result:resultName,youLeft:s.you.length,botLeft:s.bot.length,outcome,rewardPoints}});if(!result)return r.status(409).json({error:'La partida ya terminó o no existe.'});r.json(result)}));
