app.post('/api/chess/move',verified,csrf,wrap(async(q,r)=>{const {gameId,from,to,promotion}=q.body;if(typeof gameId!=='string'||!/^([a-h][1-8])$/.test(from)||!/^([a-h][1-8])$/.test(to))return r.status(400).json({error:'Movimiento no válido.'});const result=await tx(async c=>{const row=await c.query(`SELECT state,status FROM game_sessions WHERE id=$1 AND user_id=$2 AND game_id='ajedrez' AND mode='bot' FOR UPDATE`,[gameId,q.session.uid]);if(!row.rowCount||row.rows[0].status!=='active')return{error:'La partida no está activa.'};const game=new Chess(row.rows[0].state.fen),legal=game.moves({verbose:true}),promote=['q','r','b','n'].includes(promotion)?promotion:'q',candidate=legal.find(m=>m.from===from&&m.to===to&&(!m.promotion||m.promotion===promote));if(!candidate)return{error:'Movimiento ilegal.'};const playerMove=game.move(candidate);let botMove=null;if(!game.isGameOver()){const moves=game.moves({verbose:true}),choice=moves[crypto.randomInt(moves.length)];botMove=game.move(choice)}const state={fen:game.fen(),pgn:game.pgn()},playerWin=game.isCheckmate()&&game.turn()==='b';await c.query(`UPDATE game_sessions SET state=$2,status=$3,score=$4,finished_at=CASE WHEN $3='complete' THEN now() ELSE finished_at END WHERE id=$1`,[gameId,JSON.stringify(state),game.isGameOver()?'complete':'active',game.isGameOver()?(playerWin?1:0):0]);const rewardPoints=playerWin?await awardGameWin(c,q.session.uid,gameId,25):0;if(playerWin)await c.query('UPDATE game_sessions SET reward_points=$2 WHERE id=$1',[gameId,rewardPoints]);return{fen:game.fen(),board:game.board(),turn:game.turn(),pgn:game.pgn(),playerMove:playerMove.san,botMove:botMove?.san||null,gameOver:game.isGameOver(),checkmate:game.isCheckmate(),draw:game.isDraw(),rewardPoints,legalMoves:game.isGameOver()?[]:game.moves({verbose:true})}});if(result.error)return r.status(400).json({error:result.error});r.json(result)}));
