app.post('/api/ads/gam-revenue',wrap(async(q,r)=>{const secret=process.env.GAM_REVENUE_IMPORT_KEY;if(!secret)return r.status(503).json({error:'Importación publicitaria no configurada.'});const auth=String(q.get('authorization')||''),supplied=auth.startsWith('Bearer ')?auth.slice(7):'';if(!same(secret,supplied))return r.sendStatus(401);const day=String(q.body.date||''),amount=Number(q.body.revenue);if(!/^\d{4}-\d{2}-\d{2}$/.test(day)||day!==new Date().toISOString().slice(0,10)||!Number.isFinite(amount)||amount<0||amount>1e6)return r.status(400).json({error:'Envía el total neto de hoy en USD y con fecha UTC.'});const value=amount.toFixed(6);const result=await tx(async c=>{await c.query('SELECT pg_advisory_xact_lock(hashtext($1))',['gam:'+day]);const state=await c.query('SELECT settled_at FROM daily_jackpots WHERE draw_date=$1 FOR UPDATE',[day]);if(state.rows[0]?.settled_at)return{closed:true};const old=await c.query(`SELECT revenue FROM ad_revenue_daily WHERE provider='google-ad-manager' AND draw_date=$1`,[day]);const previous=Number(old.rows[0]?.revenue||0),delta=Number(value)-previous;await c.query(`INSERT INTO ad_revenue_daily(provider,draw_date,revenue) VALUES('google-ad-manager',$1,$2) ON CONFLICT(provider,draw_date) DO UPDATE SET revenue=EXCLUDED.revenue,updated_at=now()`,[day,value]);await c.query(`INSERT INTO daily_jackpots(draw_date,revenue,jackpot_amount) VALUES($1,$2,GREATEST(0,$2*0.9)) ON CONFLICT(draw_date) DO UPDATE SET revenue=GREATEST(0,daily_jackpots.revenue+$3),jackpot_amount=GREATEST(0,daily_jackpots.jackpot_amount+$3*0.9)`,[day,value,delta]);return{closed:false,total:value,delta:delta.toFixed(6)}});if(result.closed)return r.status(409).json({error:'El sorteo de hoy ya se cerró.'});r.json({ok:true,...result})}));


async function settleYesterday(){
 const date=new Date();date.setUTCDate(date.getUTCDate()-1);const day=date.toISOString().slice(0,10);
 await tx(async c=>{const lock=await c.query('SELECT pg_try_advisory_xact_lock(7300261029) ok');if(!lock.rows[0].ok)return;
  let pot=await c.query('SELECT draw_date,jackpot_amount,settled_at FROM daily_jackpots WHERE draw_date=$1 FOR UPDATE',[day]);
  if(!pot.rowCount){pot=await c.query('INSERT INTO daily_jackpots(draw_date) VALUES($1) RETURNING draw_date,jackpot_amount,settled_at',[day])}if(pot.rows[0].settled_at)return;
  const count=await c.query('SELECT count(*)::int n FROM lottery_tickets WHERE draw_date=$1',[day]);let winner=null;
  if(count.rows[0].n){const offset=crypto.randomInt(count.rows[0].n);const selected=await c.query('SELECT id,user_id FROM lottery_tickets WHERE draw_date=$1 ORDER BY created_at,id OFFSET $2 LIMIT 1',[day,offset]);winner=selected.rows[0];await c.query('UPDATE lottery_tickets SET winner=true WHERE id=$1',[winner.id])}
  await c.query('UPDATE daily_jackpots SET winner_user_id=$2,settled_at=now() WHERE draw_date=$1',[day,winner?.user_id||null]);
 });
}
